import { useEffect, useRef, useState } from 'react';
import { JxButton, JxDivider, JxInputField, JxStepper } from '@jinx-ui/react';

export type RegistrationValues = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type FieldName = keyof RegistrationValues;

type RegistrationWizardProps = {
  onSubmit: (values: RegistrationValues) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const EMPTY_VALUES: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const SUMMARY: { field: FieldName; label: string; prefix?: string }[] = [
  { field: 'name', label: 'Имя' },
  { field: 'email', label: 'Электронная почта' },
  { field: 'phone', label: 'Телефон', prefix: '+7 ' },
  { field: 'city', label: 'Город' },
  { field: 'street', label: 'Улица и дом' },
  { field: 'zip', label: 'Почтовый индекс' },
];

function validateStep(step: number, values: RegistrationValues) {
  const errors: Partial<Record<FieldName, string>> = {};

  if (step === 0) {
    if (!values.name.trim()) errors.name = 'Укажите имя, оно попадёт в договор';
    if (!values.email.includes('@')) errors.email = 'Укажите адрес с символом @';
    if (values.phone.replace(/\D/g, '').length !== 10) errors.phone = 'Десять цифр без кода страны';
  }

  if (step === 1) {
    if (!values.city.trim()) errors.city = 'Укажите город доставки';
    if (!values.street.trim()) errors.street = 'Укажите улицу и номер дома';
    if (!/^\d{6}$/.test(values.zip.trim())) errors.zip = 'Индекс из шести цифр';
  }

  return errors;
}

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY_VALUES);
  const [showErrors, setShowErrors] = useState(false);

  const headingRef = useRef<HTMLHeadingElement>(null);
  const firstFieldRef = useRef<HTMLInputElement>(null);
  const mountedRef = useRef(false);

  const errors = showErrors ? validateStep(step, values) : {};
  const isLastStep = step === STEPS.length - 1;

  useEffect(() => {
    if (!mountedRef.current) {
      mountedRef.current = true;
      return;
    }
    if (firstFieldRef.current) firstFieldRef.current.focus();
    else headingRef.current?.focus();
  }, [step]);

  const update = (field: FieldName) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const next = event.target.value;
    setValues((current) => ({ ...current, [field]: next }));
  };

  const goBack = () => {
    setShowErrors(false);
    setStep((current) => Math.max(current - 1, 0));
  };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const stepErrors = validateStep(step, values);

    if (Object.keys(stepErrors).length > 0) {
      setShowErrors(true);
      return;
    }

    setShowErrors(false);

    if (isLastStep) onSubmit(values);
    else setStep((current) => current + 1);
  };

  return (
    <form
      onSubmit={handleSubmit}
      noValidate
      aria-labelledby="registration-step-heading"
      style={{ display: 'grid', gap: 24, maxWidth: 520, fontFamily: 'var(--jx-font-sans)' }}
    >
      <JxStepper steps={STEPS} current={step} />

      <h2
        id="registration-step-heading"
        ref={headingRef}
        tabIndex={-1}
        style={{ margin: 0, fontFamily: 'var(--jx-font-display)', fontSize: 20 }}
      >
        {`Шаг ${step + 1} из ${STEPS.length}. ${STEPS[step].label}`}
      </h2>

      {step === 0 && (
        <div style={{ display: 'grid', gap: 16 }}>
          <JxInputField
            ref={firstFieldRef}
            label="Имя и фамилия"
            name="name"
            autoComplete="name"
            required
            value={values.name}
            onChange={update('name')}
            errorText={errors.name}
          />
          <JxInputField
            label="Электронная почта"
            name="email"
            type="email"
            autoComplete="email"
            required
            value={values.email}
            onChange={update('email')}
            errorText={errors.email}
            helperText="Пришлём на неё подтверждение регистрации"
          />
          <JxInputField
            label="Телефон"
            name="phone"
            type="tel"
            autoComplete="tel-national"
            prefix="+7"
            required
            value={values.phone}
            onChange={update('phone')}
            errorText={errors.phone}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: 16 }}>
          <JxInputField
            ref={firstFieldRef}
            label="Город"
            name="city"
            autoComplete="address-level2"
            required
            value={values.city}
            onChange={update('city')}
            errorText={errors.city}
          />
          <JxInputField
            label="Улица и дом"
            name="street"
            autoComplete="street-address"
            required
            value={values.street}
            onChange={update('street')}
            errorText={errors.street}
          />
          <JxInputField
            label="Почтовый индекс"
            name="zip"
            inputMode="numeric"
            autoComplete="postal-code"
            required
            value={values.zip}
            onChange={update('zip')}
            errorText={errors.zip}
            helperText="Шесть цифр, например 190000"
          />
        </div>
      )}

      {step === 2 && (
        <dl style={{ display: 'grid', gap: 12, margin: 0 }}>
          {SUMMARY.map((row, index) => (
            <div key={row.field} style={{ display: 'grid', gap: 12 }}>
              {index > 0 && <JxDivider />}
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: 'minmax(0, 1fr) minmax(0, 1.4fr)',
                  gap: 12,
                  alignItems: 'baseline',
                }}
              >
                <dt style={{ fontSize: 14 }}>{row.label}</dt>
                <dd
                  style={{
                    margin: 0,
                    fontFamily: 'var(--jx-font-mono)',
                    overflowWrap: 'anywhere',
                  }}
                >
                  {`${row.prefix ?? ''}${values[row.field]}`}
                </dd>
              </div>
            </div>
          ))}
        </dl>
      )}

      <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
        <JxButton type="button" variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary">
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

